    sendMessage: mockSendMessage,
    checkLookupSupport: (...a: unknown[]) => mockCheckSupport(...a),
  }),
}));

vi.mock('@/services/send', async () => {
  const actual = await vi.importActual<typeof import('@/services/send')>(
    '@/services/send'
  );
  return {
    ...actual,
    sendMessage: (...a: unknown[]) => mockSendMessage(...a),
    reconcileAmbiguousSms: vi.fn(async () => ({
      unknownCount: 0,
      stuckSendingCount: 0,
      requeued: 0,
      confirmed: 0,
      parked: 0,
      needsReview: 0,
      alert: false,
    })),
    resolveRecoveryOutcome: vi.fn(async () => 'absent'),
  };
});

vi.mock('@/services/sms', () => ({
  processDeferredRecoveries: vi.fn(async () => ({
    sent: 0,
    deferred: 0,
    errors: 0,
  })),
  sendRecoverySMS: vi.fn(async () => undefined),
}));

vi.mock('@/services/suppressions', () => ({
  isPhoneSuppressed: vi.fn(async () => false),
  SuppressionLookupError: class extends Error {},
}));

import {
  claimDueEnrollment,
  leadHasActiveEnrollment,
  listClaimableEnrollmentIds,
  processDueCampaigns,
  reconcileAmbiguousSms,
} from './campaigns';

function chainable(result: { data: unknown; error: unknown }) {
  const obj: Record<string, any> = {};
  const self = () => obj;
  for (const method of [
    'select', 'insert', 'update', 'eq', 'lte', 'lt', 'is', 'or', 'in', 'like',
    'order', 'limit', 'single', 'maybeSingle',
  ]) {
    obj[method] = vi.fn(self);
  }
  obj.single = vi.fn(async () => result);
  obj.maybeSingle = vi.fn(async () => result);
  obj.select = vi.fn(() => {
    const nested = chainable(result);
    nested.then = (resolve: (v: unknown) => unknown, reject?: (e: unknown) => unknown) =>
      Promise.resolve(result).then(resolve, reject);
    return nested;
  });
  obj.update = vi.fn(() => {
    const u = chainable(result);
    u.select = vi.fn(() => chainable(result));
    return u;
  });
  obj.insert = vi.fn(() => chainable(result));
  obj.then = (resolve: (v: unknown) => unknown, reject?: (e: unknown) => unknown) =>
    Promise.resolve(result).then(resolve, reject);
  return obj;
}

describe('campaigns cron DI', () => {
  beforeEach(() => {
    mockFrom.mockReset();
    mockSendMessage.mockReset();
    mockCheckSupport.mockReset();
    mockCheckSupport.mockResolvedValue({ supported: true });
    // Speed up delay in processDueCampaigns
    vi.spyOn(global, 'setTimeout').mockImplementation(((fn: () => void) => {
      fn();
      return 0 as unknown as ReturnType<typeof setTimeout>;
    }) as unknown as typeof setTimeout);
  });

  it('listClaimableEnrollmentIds empty on error', async () => {
    mockFrom.mockImplementation(() =>
      chainable({ data: null, error: { message: 'x' } })
    );
    await expect(listClaimableEnrollmentIds(5)).resolves.toEqual([]);
  });

  it('processDueCampaigns claims and sends', async () => {
    let claimCalls = 0;
    mockFrom.mockImplementation((table: string) => {
      if (table === 'campaign_enrollments') {
        claimCalls += 1;
        // First calls: listClaimable → ids; then claim update; then send fetch
        if (claimCalls <= 2) {
          return chainable({ data: [{ id: 'enr-1' }], error: null });
        }
        const enrollmentRow = {
          id: 'enr-1',
          current_step: 2,
          status: 'active',
          claim_token: 'tok',
          leads: {
            id: 'L',
            caller_phone: '+12135550100',
            opted_out: false,
            issue: '',
            businesses: { id: 'B', name: 'Acme', timezone: 'America/New_York' },
          },
          campaigns: { id: 'C', name: 'Standard' },
        };
        const b = chainable({ data: enrollmentRow, error: null });
        b.single = vi.fn(async () => ({ data: enrollmentRow, error: null }));
        b.update = vi.fn(() => {
          const u = chainable({
            data: [{ id: 'enr-1', claim_token: 'tok' }],
            error: null,
          });
          u.select = vi.fn(() =>
            chainable({
              data: [{ id: 'enr-1', claim_token: 'tok' }],
              error: null,
            })
          );
          return u;
        });
        return b;
      }
      if (table === 'campaign_steps') {
        return chainable({
          data: [
            { step_number: 1, delay_minutes: 0, template_key: 'standard_initial' },
            { step_number: 2, delay_minutes: 60, template_key: 'standard_followup_1' },
          ],
          error: null,
        });
      }
      return chainable({ data: [], error: null });
    });

    mockSendMessage.mockResolvedValue({
      kind: 'sent',
      sid: 's',
      messageId: 'm',
      providerStatus: 'queued',
      keySupportedAtSend: true,
    });

    const r = await processDueCampaigns();
    expect(r.messagingProvider).toBe('mock');
    expect(r.relayLookupSupported).toBe(true);
  });

  it('reconcileAmbiguousSms recovery abandoned resend path', async () => {
    mockFrom.mockImplementation((table: string) => {
      if (table === 'sms_messages') {
        return chainable({
          data: [
            {
              id: '1',
              lead_id: 'L',
              message_sid: 'mlf:recovery:L:abandoned:99',
              status: 'abandoned_retry',
            },
          ],
          error: null,
        });
      }
      if (table === 'leads') {
        return chainable({
          data: {
            id: 'L',
            opted_out: false,
            caller_phone: '+12135550100',
            sms_outbound_sid: 'mlf:recovery:L',
            businesses: {
              id: 'B',
              name: 'Acme',
              timezone: 'America/New_York',
              vertical: 'plumbing',
              settings: {},
            },
          },
          error: null,
        });
      }
      return chainable({ data: null, error: null });
    });
    const r = await reconcileAmbiguousSms();
    expect(r.requeued).toBeGreaterThanOrEqual(1);
  });

  it('processDueCampaigns increments skipped when claim returns null', async () => {
    mockFrom.mockImplementation((table: string) => {
      if (table === 'campaign_enrollments') {
        // listClaimable returns an id; claim update returns empty → null token
        const b = chainable({ data: [{ id: 'enr-1' }], error: null });
        b.update = vi.fn(() => {
          const u = chainable({ data: [], error: null });
          u.select = vi.fn(() => chainable({ data: [], error: null }));
          return u;
        });
        return b;
      }
      return chainable({ data: [], error: null });
    });
    const r = await processDueCampaigns();
    expect(r.skipped).toBeGreaterThanOrEqual(1);
    expect(r.processed).toBe(0);
  });

  it('processDueCampaigns catch path parks enrollment and counts error', async () => {
    mockFrom.mockImplementation((table: string) => {
      if (table === 'campaign_enrollments') {
        const enrollmentRow = {
          id: 'enr-1',
          current_step: 2,
          status: 'active',
          claim_token: 'tok',
          leads: {
            id: 'L',
            caller_phone: '+12135550100',
            opted_out: false,
            issue: '',
            businesses: {
              id: 'B',
              name: 'Acme',
              timezone: 'America/New_York',
            },
          },
          campaigns: { id: 'C', name: 'Standard' },
        };
        const b = chainable({ data: [{ id: 'enr-1' }], error: null });
        b.single = vi.fn(async () => ({ data: enrollmentRow, error: null }));
        b.update = vi.fn((payload: unknown) => {
          (b as { _updates?: unknown[] })._updates = [
            ...((b as { _updates?: unknown[] })._updates ?? []),
            payload,
          ];
          const u = chainable({
            data: [{ id: 'enr-1', claim_token: 'tok' }],
            error: null,
          });
          u.select = vi.fn(() =>
            chainable({
              data: [{ id: 'enr-1', claim_token: 'tok' }],
              error: null,
            })
          );
          return u;
        });
        return b;
      }
      if (table === 'campaign_steps') {
        return chainable({
          data: [
            { step_number: 1, delay_minutes: 0, template_key: 'a' },
            { step_number: 2, delay_minutes: 60, template_key: 'b' },
          ],
          error: null,
        });
      }
      return chainable({ data: [], error: null });
    });
    mockSendMessage.mockRejectedValue(new Error('boom'));
    const r = await processDueCampaigns();
    expect(r.errors).toBeGreaterThanOrEqual(1);
  });

  it('claimDueEnrollment returns token on due hit', async () => {
    mockFrom.mockImplementation(() => {
      const b = chainable({
        data: [{ id: 'enr-1', claim_token: 'x' }],
        error: null,
      });
      b.update = vi.fn(() => {
        const u = chainable({
          data: [{ id: 'enr-1', claim_token: 'x' }],
          error: null,
        });
        u.select = vi.fn(() =>
          chainable({ data: [{ id: 'enr-1' }], error: null })
        );
        return u;
      });
      return b;
    });
    const tok = await claimDueEnrollment('enr-1');
    expect(tok).toBeTruthy();
    expect(typeof tok).toBe('string');
  });

  it('leadHasActiveEnrollment is true only for status active', async () => {
    mockFrom.mockImplementation(() =>
      chainable({
        data: { id: 'e', status: 'active', lead_id: 'L' },
        error: null,
      })
    );
    await expect(leadHasActiveEnrollment('L')).resolves.toBe(true);

    mockFrom.mockImplementation(() =>
      chainable({
        data: { id: 'e', status: 'paused', lead_id: 'L' },
        error: null,
      })
    );
    await expect(leadHasActiveEnrollment('L')).resolves.toBe(false);

    mockFrom.mockImplementation(() =>
      chainable({ data: null, error: null })
    );
    await expect(leadHasActiveEnrollment('L')).resolves.toBe(false);
  });
});

