    mockFrom.mockImplementation((table: string) => {
      if (table === 'sms_messages') {
        const b = chainable({
          data: [
            {
              id: '1',
              lead_id: 'L',
              message_sid: 'mlf:campaign:enr1:camp1:step:2:abandoned:9',
              status: 'abandoned_retry',
            },
          ],
