          lookupByIdempotencyKey: async () => ({
            outcome: 'sent',
            status: 'delivered',
            found: true,
          }),
        }) as never,
    });
    expect((await reconcileOneWithDeps(deps, row)).kind).toBe('resolved');

    deps = baseDeps({
      dbImpl: makeDb({}),
      adapter: () =>
        ({
          name: 'm',
          lookupByIdempotencyKey: async () => ({
            outcome: 'never_sent',
            found: false,
          }),
        }) as never,
    });
    expect((await reconcileOneWithDeps(deps, row)).kind).toBe('never_sent');

    deps = baseDeps({
      dbImpl: makeDb({}),
      adapter: () =>
        ({
          name: 'm',
          lookupByIdempotencyKey: async () => ({
            outcome: 'failed',
            status: 'failed',
            found: true,
          }),
        }) as never,
    });
    expect((await reconcileOneWithDeps(deps, row)).kind).toBe('needs_review');

    deps = baseDeps({
      dbImpl: makeDb({}),
      adapter: () =>
