  SuppressionLookupError: class extends Error {},
}));

vi.mock('@/services/quiet-hours', async () => {
  const actual = await vi.importActual<typeof import('@/services/quiet-hours')>(
    '@/services/quiet-hours'
  );
  return {
    ...actual,
