        optedOut: false,
        suppressed: false,
        suppressionLookupFailed: false,
        steps,
        currentStep: 1,
        leadTimezone: null,
      })
    ).toMatchObject({ type: 'fail', reason: 'no_claim_token' });
  });

  it('pauses on opted_out / suppressed; release_fail on lookup fail', () => {
    expect(
      planCampaignSendPre({
        enrollmentFound: true,
        claimToken: 't',
        optedOut: true,
        suppressed: false,
        suppressionLookupFailed: false,
        steps,
        currentStep: 1,
        leadTimezone: null,
      }).type
    ).toBe('pause');

    expect(
      planCampaignSendPre({
        enrollmentFound: true,
        claimToken: 't',
        optedOut: false,
        suppressed: true,
        suppressionLookupFailed: false,
        steps,
